import{_ as t,o,c as r,j as e,a as s}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/18-遭误解的相互依赖.md","filePath":"books/attached/18-遭误解的相互依赖.md","lastUpdated":1794316978000}'),n={name:"books/attached/18-遭误解的相互依赖.md"};function d(l,a,_,c,p,i){return o(),r("div",null,[...a[0]||(a[0]=[e("h3",{id:"遭误解的相互依赖",tabindex:"-1"},[s("遭误解的相互依赖 "),e("a",{class:"header-anchor",href:"#遭误解的相互依赖","aria-label":'Permalink to "遭误解的相互依赖"'},"​")],-1),e("p",null,"与当下流行的其他自助类心理读物一样，认为互相依赖是一种病态的相关理论，同样秉持着20世纪上半叶那种亲子观念，认为“快乐的儿童”一定要从不必要的依恋中挣脱开来。现在还有一些专家，依然坚持着类似的观点：真正的幸福都是来自个体内在的，并不需要依靠你的爱人或伴侣。你的幸福并不是他人的职责，他们也并不是你的附属品。每一个个体都应该自己照顾自己。不仅如此，即使这个人对你来说再亲近，也不能让他扰乱你内心的平静。若是你伴侣的行为让你感觉不安，你也应该有能力将自己拉出那种情绪的泥淖，你需要“把注意力放在自己身上”，并且时刻保持淡定。若是做不到，那就是你自己有什么问题了。或许你受别人牵绊太深了，或者说，你实在太依赖别人了，必须学着画出“自我的边界”来摆脱这种依赖的状态。",-1),e("p",null,"这种观点的基本论点在于，理想的恋爱关系必须建立在两个自我完善的人之间。这种关系非常成熟，相敬如宾，而且彼此保持着清晰的边界。若是你太过依恋自己的伴侣，你就似乎有点儿缺陷，你就应该努力进行克服，让自己变得更独立，更有“自我意识”。你整天对伴侣难舍难分，就实在是再糟糕不过了，这简直就是对伴侣依赖成瘾。而在我们的观念中，“成瘾”就是一种非常危险的预兆。",-1),e("p",null,"这种认为依恋是病态的理论，在帮助那种药物滥用的人解除毒瘾方面非常有效，这也是该理论建立的初衷。但是一旦照搬到亲密关系之中，这种机械性的应用就会产生误导，甚至危害到亲密关系。我们之前提到的电视真人秀选手卡伦，就是深受这种观念的影响。但是在生物学视角下，事情将变得全然不同。",-1)])])}const h=t(n,[["render",d]]);export{f as __pageData,h as default};
